export const CSS = `.nl-wrap{--nl-right:var(--c-accent-ink);--nl-left:var(--c-teal);display:grid;gap:10px;margin:8px 0 12px;}.nl-right{--nl:var(--nl-right);}.nl-left{--nl:var(--nl-left);}.nl-legend{display:flex;flex-wrap:wrap;gap:6px;}.nl-chip{display:inline-flex;align-items:center;gap:2px;padding:4px 10px;border-radius:999px;border:1.5px solid var(--nl);color:var(--nl);font-size:0.8rem;font-weight:600;background:var(--c-surface);}.nl-panel{background:var(--c-surface);border:1.5px solid var(--c-line);border-radius:18px;padding:6px 4px 2px;}.nl-svg{display:block;width:100%;max-width:560px;margin:0 auto;height:auto;overflow:visible;user-select:none;-webkit-user-select:none;}.nl-drag{touch-action:pan-y;cursor:pointer;}.nl-axis{stroke:var(--c-text);stroke-width:2;stroke-linecap:round;}.nl-tick{stroke:var(--c-muted);stroke-width:1.5;}.nl-zeroTick{stroke:var(--c-text);stroke-width:3;}.nl-tickText,.nl-tickZero,.nl-tickNow,.nl-markText,.nl-answerText,.nl-guessText,.nl-hopNum,.nl-tokenText{font-family:inherit;fill:var(--c-text);}.nl-tickText{font-size:11px;fill:var(--c-muted);}.nl-tickZero{font-size:12px;font-weight:700;}.nl-tickNow{font-size:13px;font-weight:700;}.nl-markText,.nl-answerText,.nl-guessText{font-size:10px;font-weight:600;}.nl-markText{fill:var(--c-muted);}.nl-answerText{fill:var(--c-success);}.nl-guessText{fill:var(--c-warning);}.nl-tokenBox{fill:var(--c-surface);stroke:var(--nl);stroke-width:2;}.nl-tokenText{fill:var(--nl);font-size:13px;font-weight:700;}.nl-arc{fill:none;stroke:var(--nl);stroke-width:2;opacity:0.75;}.nl-head{fill:var(--nl);opacity:0.85;}.nl-hopNum{font-size:10px;font-weight:700;fill:var(--nl);}.nl-hopNow .nl-arc{stroke-width:3.5;opacity:1;}.nl-hopNow .nl-head{opacity:1;}.nl-startRing{fill:none;stroke:var(--c-muted);stroke-width:2;stroke-dasharray:3 2;}.nl-answerRing{fill:none;stroke:var(--c-success);stroke-width:3;}.nl-guessRing{fill:none;stroke:var(--c-warning);stroke-width:3;stroke-dasharray:4 2;}.nl-marker{transition:transform 0.45s ease;outline:none;}.nl-still{transition:none;}.nl-markerLive{cursor:grab;}.nl-hit{fill:transparent;}.nl-ring{fill:none;stroke:transparent;stroke-width:3;}.nl-markerLive:focus-visible .nl-ring{stroke:var(--c-focus);}.nl-dot{fill:var(--nl);stroke:var(--c-surface);stroke-width:2.5;}.nl-numbers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:0;}.nl-numbers>div{background:var(--c-surface);border:1.5px solid var(--c-line);border-radius:12px;padding:6px 8px;text-align:center;}.nl-numbers dt{font-size:0.72rem;color:var(--c-muted);}.nl-numbers dd{margin:0;font-size:1.35rem;font-weight:700;color:var(--c-text);}.nl-numbers .nl-right dd,.nl-numbers .nl-left dd{color:var(--nl);}.nl-numbers .nl-final{border-color:var(--c-success);background:var(--c-success-soft);}.nl-numbers .nl-final dd{color:var(--c-success);}.nl-hint,.nl-note{margin:0;font-size:0.9rem;color:var(--c-muted);}.nl-controls{display:flex;flex-wrap:wrap;gap:8px;}.nl-btn{width:auto;flex:1 1 auto;min-height:44px;min-width:44px;padding:10px 14px;border:1.5px solid var(--c-line);border-radius:12px;background:var(--c-surface);color:var(--c-text);font-weight:600;font-size:0.92rem;}.nl-btn.nl-main{border-color:var(--c-accent-ink);color:var(--c-accent-ink);}.nl-btn:disabled{opacity:0.45;cursor:default;}.nl-slider{width:100%;min-height:44px;accent-color:var(--c-accent);}.nl-result{display:grid;gap:8px;}.nl-landed{margin:0;font-size:1.15rem;font-weight:700;}.nl-good,.nl-tip{margin:0;padding:10px 12px;border-radius:12px;font-size:0.95rem;}.nl-good{background:var(--c-success-soft);color:var(--c-success);}.nl-tip{background:var(--c-warning-soft);color:var(--c-warning);}.nl-refused{margin:8px 0;padding:10px 12px;border-radius:12px;background:var(--c-warning-soft);color:var(--c-warning);}.nl-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;}@media (prefers-reduced-motion:reduce){.nl-marker{transition:none;}}`;
